// Check if a user has admin privileges using the has_role RPC function
export const isAdminUser = async (userId: string | undefined): Promise<boolean> => {
  if (!userId) return false;
  
  try {
    // Use type assertion to bypass TypeScript's strict checking for RPC function
    const { data, error } = await (supabase.rpc as any)('has_role', { 
        user_id: userId, 
        required_role: 'admin' 
      });
    
    if (error) {
      console.error("Error checking admin role:", error);
      return false;
    }
    
    return data || false;
  } catch (err) {
    console.error("Error checking admin status:", err);
    return false;
  }
};
